css:
:scope { width: min(100%, 1338px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 20; grid-row: 1 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; color: var(--os-color-link); }
.gx__i2 { grid-column: 1 / span 20; grid-row: 5 / span 23; font-family: var(--os-font-heading); font-size: 104.4px; font-weight: 700; line-height: 0.86; letter-spacing: -0.035em; color: var(--os-color-text); }
.gx__i3 { grid-column: 1 / span 15; grid-row: 34 / span 11; font-family: var(--os-font-body); font-size: 24.1px; font-weight: 400; line-height: 1.25; letter-spacing: 0em; font-style: italic; color: var(--os-color-text); }
.gx__i4 { grid-column: 1 / span 13; grid-row: 48 / span 13; font-family: var(--os-font-body); font-size: 18.2px; font-weight: 400; line-height: 1.38; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i5 { grid-column: 22 / span 3; grid-row: 69 / span 2; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 400; line-height: 1.4; letter-spacing: 0.16em; text-transform: uppercase; text-align: right; color: var(--os-color-link); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 84px; }
  .gx__i3 { font-family: var(--os-font-body); font-size: 19px; }
  .gx__i4 { font-family: var(--os-font-body); font-size: 15px; }
  .gx__i5 { font-family: var(--os-font-label); font-size: 14px; }
}
